# Drop duplicate brand/model combinations. Preserve distinct products but never duplicate an exact official model key.
unique=[];seen=set()
for r in rows:
 key=(r['brand'].lower(),r['model'].lower())
 if key in seen:continue
 seen.add(key);unique.append(r)
rows=unique
for r in rows:
 if r['brand']=='Nikon' and r['model'] in ('ZR','Z5II'):
  r['release_year']='2025'
  release_source='https://www.nikon.co.in/articles/press-release/nikon-enters-cinema-space-with-nikon-zr-brings-cinematic-precision-to-a-compact-all-in-one-body' if r['model']=='ZR' else 'https://www.nikon.co.in/articles/press-release/nikon-sets-new-standard-with-stunning-autofocus-abilities-powerful-low-light-performance-with-z5ii'
  release_day='2025-09-10' if r['model']=='ZR' else '2025-04-03'
  r['notes']=(r['notes'].rstrip(' .;')+'; ' if r['notes'] else '')+f'Release year supported by Nikon India press release dated {release_day}: {release_source}.'
 else:
  r['release_year']=''
  r['notes']=(r['notes'].rstrip(' .;')+'; ' if r['notes'] else '')+'Release year not verified from the product source; age needs review.'
for r in rows:
 missing=[]
 if not r['release_year']:missing.append('release year not verified')
 if not r['official_price']:missing.append('official listed price not captured')
 if not r['image_url']:missing.append('official product image URL not captured')
 if r['specifications_json']=='{}':missing.append('detailed specifications not captured')
 if missing:r['notes']=(r['notes'].rstrip(' .;')+'; ' if r['notes'] else '')+'Missing/unverified fields: '+', '.join(missing)+'.'
with open(OUT,'w',encoding='utf-8-sig',newline='') as f:w=csv.DictWriter(f,fieldnames=FIELDS);w.writeheader();w.writerows(rows)
print('J records',len(rows),'brands',len(set(r['brand'] for r in rows)),'subtypes',dict(sorted(Counter(r['subcategory'] for r in rows).items())))
print('Missing year',sum(not r['release_year'] for r in rows),'price',sum(not r['official_price'] for r in rows),'image',sum(not r['image_url'] for r in rows),'specs',sum(r['specifications_json']=='{}' for r in rows),'duplicates',len(rows)-len(seen))
